// Viṣṇu Sahasranāma — concepts 201–300 (English, own paraphrases).
// Same conventions as vs-concepts-001-100.ts.
export const vsConcepts201300: any[] = [
  { id: "vs-nama-201", title: "Sandhātā", category: "Teacher", summary: "The joiner of sundered things. From sandhā, to join: He resets dislocated joints, reconciles estranged parties, and re-knits the devotee's own halves that fear splits apart. The verse stations Him beside the lion, so joining here is rescue-work — Narasiṃha's claws tore empire so that wholeness could be re-joined. Śaṅkara's lineage reads sandhātā as the Lord who holds creation's articulations together. Mend one breach today, outer or inner. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-202", title: "Sandhimān", category: "Teacher", summary: "The joined, who wears limitation as garment. Sandhimat names the Lord as conditioned by the very joints He ties — present inside bonds, time, and bodies as though limited by them. The paradox is deliberate: the joiner enters the joint, the unlimited consents to appear jointed so the sundered can be reached. Where sandhātā names the act of mending, sandhimān names its cost — nearness. Wear one limitation gracefully instead of resenting it. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-203", title: "Sthiraḥ", category: "Teacher", summary: "The constant, firm amid flux. Sthira is fixity as fidelity: He never shifts stance, never abandons post, never revises His promise when circumstances turn. Joints hold because something in them does not wobble — the hymn places firmness immediately after joining so that reconciliation rests on reliability rather than mood. Devotion borrows this steadiness: the fickle mind steadies by leaning on the Fixed. Hold one post firmly today without renegotiating. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-204", title: "Ajaḥ", category: "Teacher", summary: "The unborn, here wearing birth as costume (named again). Aja denies beginning to the Beginningless, yet the tradition reads this occurrence as Brahmā's form assumed — birthlessness playing the born so that creation has a face. The unborn can act as the born without ceasing to be unborn, as an actor remains himself inside the role. Repetition of the name is itself doctrine: the birthless returns wherever beginnings need authorizing. Play one role lightly, remembering the actor. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-205", title: "Durmarṣaṇaḥ", category: "Teacher", summary: "Who cannot be vanquished or withstood. Durmarṣaṇa is resistance-proof: opposition breaks on Him as ocean breaks on cliff, and no force — demonic, karmic, or inner — overbears His ordinance. The name stands mid-verse as the lion's temper translated into metaphysics: gentleness toward devotees, adamant against their destroyers. Śaṅkara's lineage stresses inability rather than unwillingness — He cannot be withstood because there is no outside from which to withstand. Stand one rock-firmness today. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-206", title: "Śāstā", category: "Teacher", summary: "The ruler and instructor of the universe. Śāstṛ fuses command with teaching: every ordinance is a lesson, every law a lecture, and punishment itself is pedagogy — the rod that schools. The Gītā's Kṛṣṇa stands behind this name, ruling Arjuna by instructing him rather than overpowering him. Irresistibility (the previous name) thus expresses as instruction: might that explains itself instead of merely crushing. Learn one ordinance today as a lesson, not a burden. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-207", title: "Viśrutātmā", category: "Teacher", summary: "He whose Self is famed in the Vedas. Viśruta-ātman makes scripture's celebrity substantial: He is famous because He is real, and renown follows being as fragrance follows flower — the reverse of worldly fame, which often precedes or replaces substance. Power legitimated by scripture is the verse's theme: lion-force (siṃha) bound to Veda-fame, so that might never reads as mere force. Build one reputation on being rather than display. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-208", title: "Surārihā", category: "Teacher", summary: "Destroyer of the gods' enemies. Surārihan names heaven's defence as personal: when the devas' distress sounds, He answers as though His own household were attacked — which, the tradition notes, it is, since the gods are His own administrative body. The verse closes on this martial note so that teaching (śāstā) and fame (viśrutātmā) are seen guarded, not merely proclaimed. Protection is the epilogue of instruction. Answer one distress call today as though it were your own. (Stotra verse 22.)", relatedVerseIds: ["vs-022"] },
  { id: "vs-nama-209", title: "Guruḥ", category: "Teacher", summary: "The teacher of all knowledge. Guru is weightiness that steadies: every lesson ever learned was His lending, every science a withdrawal from His account. The verse gathers the previous arc — joining, firmness, rule, fame, defence — into pedagogy: all of it was teaching. Śaṅkara's lineage reads guru as dispeller of darkness by weight of being rather than by volume of words. Learn once today as borrowing, and acknowledge the Lender. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-210", title: "Gurutamaḥ", category: "Teacher", summary: "The teacher of teachers. Gurutama superlatives pedagogy's source: gurus graduate from this Guru, guidance derives from Guidance, and every lineage-holder holds a borrowed lamp. The comparative (guru) becoming superlative (gurutama) teaches humility inside hierarchy — eminence exists, but it terminates upward in Him rather than in any human claimant. Thank one teacher's Teacher today, going one rung above gratitude's usual stop. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-211", title: "Dhāma", category: "Teacher", summary: "The supreme abode. Dhāman is arrival's address and radiance together — both the place where journeys end and the light by which they travel, home and lamp in one word. Every homecoming ends here, every exile returns hither; lessons lodge where the Teacher dwells. The verse places abode between the greatest teacher and truth itself: dwell in instruction and you already dwell in Him. Come home once inwardly today instead of circling. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-212", title: "Satyaḥ", category: "Teacher", summary: "Truth Himself (named again). Repetition underscores: truth bears repeating because falsehood repeats unasked, and each recurrence of this name in the hymn re-anchors the intervening names in reality. Satya is not a property He has but the person He is — honesty is likeness to Him, every exact word a small incarnation, as the Upaniṣads call truth Brahman's face. Repeat one truth today precisely, without embroidery. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-213", title: "Satyaparākramaḥ", category: "Teacher", summary: "He whose valour is truthful. Satya-parākrama weds courage to honesty: bravado bluffs, valour verifies, and true fighting never needs false reports, inflated odds, or hidden motives. The name guards the teacher-arc against manipulation — instruction backed by force must be force purified by truth. The Satyabhāṣyam delights in this compound as ethics inside omnipotence. Fight one fight honestly today, winning or losing without deceit. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-214", title: "Nimiṣaḥ", category: "Teacher", summary: "The winking, whose blinking is creation's rhythm. Nimiṣa names the Lord as time blinking through creatures — eyes closing in contemplation, worlds opening and shutting with His lids, beings born and withdrawn in each cosmic blink. Temporality worn as a garment: He consents to rhythm, to opening and closing, so that finite life can breathe inside His eternity. Blink once contemplatively today, feeling the rhythm as His. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-215", title: "Animiṣaḥ", category: "Teacher", summary: "The unwinking, ever-vigilant Lord. Animiṣa is sleeplessness divine: the gods are called the unwinking ones, and He is their unwinking archetype — attention without fatigue, guardianship without blinking, knowledge never interrupted by sleep. Paired with nimiṣa, the two names wear temporality and eternity together: He blinks in creatures, never blinks as Himself. Trust one sleepless vigilance over your life tonight. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-216", title: "Sragvī", category: "Teacher", summary: "Wearer of the unfading garland. Sragvin wears Vaijayantī, the victory-garland of wildflowers that never wilts: honour perpetually in bloom, triumph flowering without season. The verse garlands the teacher — learning as festival, instruction crowned — so that pedagogy never reads as drudgery. What never fades on Him can unfade in the learner: truths once strung need not be re-strung. Wear one unfading honour humbly today. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-217", title: "Vācaspatirudāradhīḥ", category: "Teacher", summary: "Lord of speech with noble mind — one name, vācaspati joined to udāradhī. Eloquence serves nobility: words are magnificent because thought is magnanimous, and utterance carries weight only when mind carries generosity. The teacher-arc closes on speech perfected — instruction's instrument tuned by character's breadth. Śaṅkara's lineage stresses the compound's order: lordship of speech derives from largeness of mind, never the reverse. Speak once today nobly-minded rather than cleverly. (Stotra verse 23.)", relatedVerseIds: ["vs-023"] },
  { id: "vs-nama-218", title: "Agraṇīḥ", category: "Teacher", summary: "The foremost guide to the peak. Agraṇī leads by priority in climbing: He goes first up every steep, so following is never blind — the path has footprints. Leadership as precedence rather than command; the guide's authority is the dust of His sandals on the trail ahead. The verse descends from guide to host-leader to wind: direction beginning as a person before diffusing as presence. Follow one steep upward today behind His precedence. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-219", title: "Grāmaṇīḥ", category: "Teacher", summary: "Leader of the flock, chief of hosts. Grāmaṇī heads every gathering from village to cosmos: multitudes need a head, and He is the head that multitudes — of men, of gods, of stars — already have whether they acknowledge it or not. From the foremost guide (agraṇī) to the host's chief, leadership widens from path to people. No gathering is headless; the question is only whether its head is recognized. Gather once today headed, acknowledging Him. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-220", title: "Śrīmān", category: "Teacher", summary: "Possessor of glory and effulgence (named again). Glory re-possessed each telling: Śrī returns in the hymn the way Lakṣmī returns to His chest — never exhausted by previous mention, abundance restated because abundance is inexhaustible. Here splendour stands amid leadership names, teaching that command without glory is mere administration, and glory without command mere decoration. Restate one glory today — praise Him again for an old mercy. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-221", title: "Nyāyaḥ", category: "Teacher", summary: "Justice itself. Nyāya is fairness enthroned as person: right is not a rule but a ruler, equity with a face, logic with a heart. Sandwiched between glories in the verse, justice reads as splendour rather than machinery — fairness gorgeous, not merely procedural. The tradition's logicians (Naiyāyikas) lend the word its edge: reasoning itself is His shape. Judge one matter justly today, gorgeously rather than grudgingly. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-222", title: "Netā", category: "Teacher", summary: "The leader of the world. Netṛ is guidance global: every march has its Marshal, visible or veiled, and history's columns move under orders they did not issue to themselves. After justice (nyāya), leadership reads as equity in motion — direction with a conscience. The name is spare, almost bare, as though leadership at its highest needs no adjectives. March once today guided, checking direction against justice. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-223", title: "Samīraṇaḥ", category: "Teacher", summary: "The wind. Samīraṇa guides as breeze rather than baton: motion's god moving unseen, felt only in effects — dust rising, banners stirring, breath continuing. Leadership dissolves into atmosphere here: after guide, host-chief, glory, justice and marshal comes the gentlest governance of all, persuasion without pressure. The Upaniṣads call wind the sutra-thread of the world; this name makes the thread personal. Move once today breezily, influencing without imposing. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-224", title: "Sahasramūrdhā", category: "Teacher", summary: "Thousand-headed. Sahasra-mūrdhan crowns the leadership arc with the Puruṣa-sūkta cosmos: every mind crowned by this Mind, all thoughts headed upward, headship infinite because heads are innumerable. From wind's invisibility the hymn explodes into cosmic visibility — the breezy guide has a thousand faces. No thought is headless; each has His head above it. Crown one thought upward today, referring it to the thousand-headed Mind. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-225", title: "Viśvātmā", category: "Teacher", summary: "Soul of the universe. Viśvātman names interiority cosmic: the world's inside is His inside, subjectivity universal, and every creature's inwardness opens onto one Inwardness. After the thousand heads, this name gathers multiplicity into unity — many crowns, one Soul. The leader of hosts turns out to be the hosts' own Self. Feel one world inside today: another's inwardness as His, and therefore as kin to yours. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-226", title: "Sahasrākṣaḥ", category: "Teacher", summary: "Thousand-eyed. Sahasrākṣa watches salvifically: every glance guards, no seeing is idle curiosity, and omnipresence begins as attentiveness — no cry faces an averted eye, no quarter lacks His countenance. The Puruṣa-sūkta's cosmic Person continues: heads, then soul, then eyes. Surveillance here is shepherding, not spying; to be seen through is to be seen after. Guard once today by glancing — notice someone the way He notices. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-227", title: "Sahasrapāt", category: "Teacher", summary: "Thousand-footed. Sahasrapāt walks to every sufferer: approach infinite, distance dissolved in feet, no affliction too remote for arrival. The cosmic Person completes — heads that think, eyes that watch, feet that come. Leadership ends in visitation: the foremost guide (agraṇī) who went first up the steep now walks last into the low places. Walk once today toward suffering rather than away. (Stotra verse 24.)", relatedVerseIds: ["vs-024"] },
  { id: "vs-nama-228", title: "Āvartanaḥ", category: "Wheel", summary: "Who turns the wheel of becoming. Āvartana rotates governance: ages revolve because He revolves them, cycles are His sceptre, and time's turning is an act rather than an accident. The wheel-arc opens with agency — turning before withdrawing — so that transcendence never reads as indifference. He turns what He transcends. Turn one cycle consciously today: a habit, a season, a day — with the Turner in view. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-229", title: "Nivṛttātmā", category: "Wheel", summary: "Detached in Self amid the turning. Nivṛtta-ātman is withdrawal within working: the Turner untouched by turns, lotus in whirlpool, operator never captured by the machine. Action without adhesion — the Gītā's detached actor writ as God's own nature. After the turning wheel, this name stills the devotee's anxiety: what turns you does not turn Him, and His stillness is available inside your motion. Work once today detached, lotus-like. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-230", title: "Saṃvṛtaḥ", category: "Wheel", summary: "Self-concealed. Saṃvṛta veils glory so that seekers may seek: hiddenness is holiness' habit, treasure buried for finding, the Beloved behind the curtain deepening love by delay. Concealment here is mercy, not absence — the withdrawn Self (previous name) further withdraws its visibility while maintaining its operation. What is hidden is not gone; it is reserved. Seek one hiddenness today instead of demanding display. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-231", title: "Sampramardanaḥ", category: "Wheel", summary: "Crusher of evildoers. Sampramardana mills oppression fine: wickedness ground to powder, tyranny powdered so that crops — the humble growing things — can breathe. Crushing here is maintenance, not malice: weeds pulled, not gardens burned. The concealed Lord (saṃvṛta) is not inactive; His hiddenness covers a mill. Let one old pattern be crushed today — name the weed and yield it to the mill. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-232", title: "Ahaḥ saṃvartakaḥ", category: "Wheel", summary: "Turner of day, maker of daylight as the Sun. Ahas-saṃvartaka manufactures dawn daily: light issued, not accidental, morning delivered like a letter with the Sun as seal. From cosmic wheel-turning the hymn narrows to the most familiar revolution — today's sunrise — so that cosmology becomes calendar. Every dawn is a small creation ex nihilo, darkness unmade and world re-issued. Dawn once deliberately tomorrow: wake to receive the issue. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-233", title: "Vahniḥ", category: "Wheel", summary: "Fire, carrier of oblations. Vahni bears offerings upward: the flame that conveys ghee to gods, hunger holy because it hungers for giving. Fire is the wheel's first lever — day's maker (previous name) kindled into altar-shape. The tradition reads vahni as the mouth of gods: what flame receives, heaven tastes. Burn one impurity today as oblation, feeding the flame something you are glad to lose. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-234", title: "Anilaḥ", category: "Wheel", summary: "Wind, air in motion. Anila is the world's respiration: ages inhaled, beings exhaled, the cosmos breathing in His chest. Beside fire (vahni), wind is the wheel's second lever — flame needs breath, sacrifice needs air, and creation needs circulation. Breath cosmic makes breath personal: your inhalation is a loan from His exhalation. Breathe cosmically once today, feeling the loan. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-235", title: "Dharaṇīdharaḥ", category: "Wheel", summary: "Bearer of the earth. Dharaṇīdhara carries ground itself: soil sustained from beneath by patience infinite — Varāha's tusks and Śeṣa's hoods are this patience given mythic shape. Fire and wind are levers; earth-bearing is the load they serve. Every step rests on carried ground, not self-supporting stone. Thank the Bearer underfoot today: tread once as on patience, not pavement. (Stotra verse 25.)", relatedVerseIds: ["vs-025"] },
  { id: "vs-nama-236", title: "Suprasādaḥ", category: "Wheel", summary: "Most gracious, mercy superlative. Suprasāda is favour beyond desert: kindness past accounting, grace that exceeds the devotee's eligibility and the ritual's exactness. The verse opens on grace so that the wheel's turnings — crushing, burning, bearing — are read inside mercy rather than mechanism. Superlative prefix (su-pra) insists: not merely gracious but gracious to excess. Receive one unmerited grace today without arguing worthiness. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-237", title: "Prasannātmā", category: "Wheel", summary: "Ever-pure and blissful in Self. Prasanna-ātman names serenity essential: clarity His climate, joy His weather, the Self's surface ever untroubled whatever storms cross it. Grace (previous name) flows from this serenity — giving is easy to the ever-content, and mercy costs nothing to fullness. Devotion borrows the climate: approach the serene and grow serene. Enjoy one serene hour today, weather-independent. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-238", title: "Viśvadhṛk", category: "Wheel", summary: "Supporter of the universe. Viśvadhṛt maintains existence moment by moment: being serviced continuously, upkeep universal, the world held up the way breath holds up song. Creation was the first act; support is creation continued past its first instant into every instant. Grace and serenity (previous names) express as maintenance — mercy doing daily work. Maintain one thing faithfully today as His subcontractor. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-239", title: "Viśvabhuk", category: "Wheel", summary: "Enjoyer of the universe. Viśvabhuj tastes worlds: existence savoured, creation relished, the All experienced from inside as delight rather than administered from outside as duty. Support (previous name) ripens into enjoyment — upkeep that loves its work, the householder delighting in the house he maintains. The world is not His burden but His banquet. Relish one existence-moment today deliberately, tasting it as He tastes. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-240", title: "Vibhuḥ", category: "Wheel", summary: "The pervader, Lord of many forms. Vibhu is one presence in countless presentations: pervasion plural, unity wearing multiplicity the way light wears colours. After supporter and enjoyer, pervasion explains both — He maintains and relishes from inside every form because He fills every form. No presentation is foreign; each is a dialect of His presence. Greet one presentation today — an unlikely person, a dull task — as His dialect. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-241", title: "Satkartā", category: "Wheel", summary: "Honourer of the good. Satkartṛ salutes virtue: goodness recognized, merit garlanded, worth acknowledged — the universe's Lord pausing to honour a good heart. Worship reverses direction here: before the good honour Him (next name), He honours the good first. Grace takes the initiative; devotion answers. Honour one good person concretely today, following His precedence. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-242", title: "Satkṛtaḥ", category: "Wheel", summary: "Honoured by the good. Satkṛta receives worship back: the worshipped worshipped, devotion reciprocated, honour circulating between Lord and devotee like garlands exchanged. With satkartā (previous name) this forms a circuit — He honours the good, the good honour Him — and the circuit is itself the teaching: relationship, not transaction. Return one honour today: answer someone's regard with regard. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-243", title: "Sādhuḥ", category: "Wheel", summary: "The righteous, walker of the straight path. Sādhu is straightness saintly: no crookedness in conduct, no bend in word, the direct road walked directly. Honour circulates (previous names) around this straightness — goodness recognized because goodness is recognizable, its geometry plain. The name also blesses the human sādhu: every straight walker participates in the Straight One. Walk one straight mile today, unbent by convenience. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-244", title: "Jahnuḥ", category: "Wheel", summary: "Jahnu, the sage-king who sipped Gaṅgā's pride. The legend: Gaṅgā descended roaring, Jahnu drank her in one sip to humble her flood, releasing her afterward as his daughter Jāhnavī. Guidance tested by swallowing heaven's river — authority proved by digesting force rather than damming it. Among honour-names this one warns: even sacred floods need sipping. Sip one pride today — your own or another's — the Jahnu way. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-245", title: "Nārāyaṇaḥ", category: "Wheel", summary: "Nārāyaṇa, abode on the waters, indweller of all beings. Nārāṇām ayanam — refuge of men, or He whose abode (ayana) is the waters (nārāḥ): beings floated in being, creation cradled on the causal sea. The verse's arc from grace to honour to righteousness docks here: all of it floated on these waters. Cosmos ends in harbour. Float one care on those waters today instead of carrying it ashore. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-246", title: "Naraḥ", category: "Wheel", summary: "Man, the human led from within. Nara closes the great verse inside the small: after Nārāyaṇa the cosmic, nara the human — the universe's Lord wearing the species He leads, humanity headed by its own perfection. The cosmic ends in the human on purpose: human birth is authorized as His address, not His exile. The wheel that turned worlds parks at your door. Lead one human kindly today, beginning with yourself. (Stotra verse 26.)", relatedVerseIds: ["vs-026"] },
  { id: "vs-nama-247", title: "Asaṅkhyeyaḥ", category: "Wheel", summary: "Of numberless forms. Asaṅkhyeya surrenders arithmetic: counting kneels, statistics confess inadequacy, and every census of His glories ends in remainder — more. Numberlessness founds law (next names show): because He exceeds count, His ordinances bind every counter. Infinity is not vagueness but superabundance of precision beyond tally. Count once today surrenderingly: enumerate blessings until enumeration fails, and worship the remainder. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-248", title: "Aprameyātmā", category: "Wheel", summary: "Of unknowable Self, beyond knowledge's instruments. Aprameya-ātman ends epistemology in awe: rule, scale and proof return empty, and the Immeasurable by which measures measure declines to be measured. This restates the early aprameya (name 46) at higher altitude — after the wheel, the turning, the grace — so that experience deepens mystery rather than dissolving it. Proof bows to presence. Know once today unknowingly: stand before Him without instruments. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-249", title: "Viśiṣṭaḥ", category: "Wheel", summary: "Transcendent in glory, distinguished past compare. Viśiṣṭa is eminence effortless: distinction without striving, rank without rivalry, excellence that never competes because competition presumes peers. After numberlessness and unknowability, distinction reads as mercy — the Indistinguishable consents to stand out so devotion has somewhere to look. Excel today without competing: one act distinguished by love, not by comparison. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-250", title: "Śiṣṭakṛt", category: "Wheel", summary: "Maker of law for the disciplined. Śiṣṭakṛt architects conduct: ordinances as building-code, character engineered to bear weight, the disciplined (śiṣṭa) given structure worthy of their discipline. Law from numberlessness (verse theme): the Boundless binds — not paradox but pedagogy, infinity giving finite feet a path. Ordinance is architecture, not cage. Build one conduct to code today: square a single habit. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-251", title: "Śuciḥ", category: "Wheel", summary: "The impeccable, pure one (named again). Purity reaffirmed lest familiarity dull it: stainlessness restated after law-making, so that ordinance never reads as stain — the Lawgiver is Himself the stainless, and His codes cleanse rather than soil. Repetition here is polish, each recurrence burnishing what use may have dimmed. Polish one purity today: a habit, a word, a motive — burnished, not replaced. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-252", title: "Siddhārthaḥ", category: "Wheel", summary: "He whose aims are all accomplished. Siddhārtha is purpose perfected: nothing pending, nothing postponed, all achieved — the name the Buddha-to-be bore, here restored to its divine owner. Prayer leans on this completion: petition addresses One whose own aims never hang fire. The verse's siddhi-cluster opens here, moving from His accomplishment to our receiving. Achieve one aim fully today, however small, in His completed image. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-253", title: "Siddhasaṅkalpaḥ", category: "Wheel", summary: "He whose resolves always succeed. Siddhasaṅkalpa unites wishing and winning: resolve and result one motion, will omnipotent because will is pure — no static between intention and event. Where siddhārtha (previous name) celebrates accomplished ends, this celebrates unfailing means: His very intending is already succeeding. Devotion borrows resolve by aligning it. Resolve one success today, then align the resolve with His before executing. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-254", title: "Siddhidaḥ", category: "Wheel", summary: "Giver of success and benedictions. Siddhida distributes attainment: fruits handed out, favours granted, the accomplished Lord (previous names) turning accomplisher of others. Prayer's whole economy lives here — asking presumes a Giver, and the Giver presumes asked-ness. Grace that accomplished itself now accomplishes devotees. Grant one success generously today, imitating the Giver in miniature. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-255", title: "Siddhisādhanaḥ", category: "Wheel", summary: "Aid and means for success. Siddhisādhana provides ladders, not only fruits: method with gifts, guidance with grants, the how alongside the what. The siddhi-cluster completes — aims, resolves, gifts, means — so that no petitioner can say the Giver gave harvest but hid the sickle. Grace is thorough. Use one provided means today instead of praying only for ends. (Stotra verse 27.)", relatedVerseIds: ["vs-027"] },
  { id: "vs-nama-256", title: "Vṛṣāhī", category: "Wheel", summary: "Controller of the rain of dharma. Vṛṣāhin showers righteousness as monsoon showers fields: merit precipitated on parched lands, duty raining where aridity reigned. The vṛṣa-cluster opens with weather — dharma as climate before dharma as beast, ladder, or womb — because righteousness, like rain, arrives from above and soaks downward. No field earns rain; it receives it. Shower one righteousness today: an unexacted right act, monsoon-like. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-257", title: "Vṛṣabhaḥ", category: "Wheel", summary: "Bull showering dharma. Vṛṣabha gives righteousness muscle: power ploughing merit's fields, strength enlisted in morality's service, the bull's shoulders under duty's yoke. After rain (previous name) comes the ploughman — heaven's water needs earth's labour, grace needs muscle. Dharma is not only showered but hauled. Plough one merit-field today: put shoulders under a right thing. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-258", title: "Viṣṇuḥ", category: "Wheel", summary: "The all-pervader (named again). Pervasion restated mid-dharma: righteousness not merely preached but pervaded, duty filled from inside rather than policed from outside. The hymn's own signature-name returns exactly where dharma peaks, identifying the pervader as dharma's substance — to pervade is to righteous-ize. Pervade one duty today: fill it from inside instead of performing it from outside. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-259", title: "Vṛṣaparvā", category: "Wheel", summary: "Ladder of dharma with jointed steps. Vṛṣaparvan graduates ascent: righteousness climbed rung by rung, elevation engineered, no leap demanded where steps suffice. Parvan is both joint and festival-knot — each rung a small celebration of rise. After rain, bull, and pervasion comes architecture: dharma climbable. Climb one rung today deliberately, celebrating the small elevation. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-260", title: "Vṛṣodaraḥ", category: "Wheel", summary: "Womb of dharma. Vṛṣodara gestates righteousness: merit conceived within, carried to term, delivered in due season — duty as pregnancy rather than performance. The masculine God wears the maternal metaphor without strain, as elsewhere He wears the womb of worlds. What is gestated cannot be hurried; it can only be carried faithfully. Conceive one merit inwardly today and begin carrying it. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-261", title: "Vardhanaḥ", category: "Wheel", summary: "Nurturer and nourisher. Vardhana fosters growth: increase encouraged, expansion fed, the young of every kind — plants, plans, persons — watered toward stature. After dharma's rain, bull, ladder and womb comes nursing: what was conceived must be fed. Grace nurses what grace conceived. Feed one growth today: attention, the cheapest and richest nourishment. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-262", title: "Vardhamānaḥ", category: "Wheel", summary: "Ever-expanding Himself. Vardhamāna is growth essential: increase as being, enlargement as existence, the Lord not merely growing things but growing — infinity expressing as expansion. The nurturer (previous name) turns out to be the growth He nurses, gardener and garden one life. Stagnation has no divine precedent. Expand once today expansively: one generosity slightly beyond comfort. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-263", title: "Viviktaḥ", category: "Wheel", summary: "Ever standing apart, separate amid all. Vivikta is detachment pristine: present yet unmixed, involved yet unstained, expanding (previous name) without entangling. Growth pairs with apartness so that abundance never becomes adhesion — He increases without clinging to increase. The devotee's model: enlarge holdings, keep hands open. Stand apart once today purely: engaged, yet unmixed. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-264", title: "Śrutisāgaraḥ", category: "Wheel", summary: "Ocean of scriptures. Śrutisāgara is revelation shoreless: texts wave upon wave, meaning fathomless, the Veda's depth receiving every river of inquiry without overflowing. The dharma-cluster closes on scripture — rain, bull, ladder, womb, growth, apartness all authenticated by the ocean they flow toward. Wade one wave deeply today: a single verse, fathomed rather than skimmed. (Stotra verse 28.)", relatedVerseIds: ["vs-028"] },
  { id: "vs-nama-265", title: "Subhujaḥ", category: "Wheel", summary: "Graceful-armed Lord. Subhuja shapes strength shapely: arms aesthetic, power proportioned, might moulded — force with form, rescue with grace. The new verse opens on beauty of limb before hard-to-hold mystery, teaching that His power arrives handsomely. Arms that bear worlds (elsewhere) are here admired as arms. Shape one strength gracefully today: let a strong act be also a beautiful one. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-266", title: "Durdharaḥ", category: "Wheel", summary: "Hard to hold, incomprehensible even to yogīs. Durdhara defeats grasp upward: adepts confess inadequacy, embrace exceeds arms, and the fair-armed Lord (previous name) declines to be seized. Seizing fails where singing succeeds; the closed fist must open into the palm of praise. Mystery is not refusal but invitation to another faculty. Hold once today unholding: carry Him in open palms. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-267", title: "Vāgmī", category: "Wheel", summary: "Eloquent in speech. Vāgmin wields utterance masterfully: words wisely chosen, sentences sculpted, truth spoken beautifully — eloquence that enriches rather than merely persuades. Beside wealth-giving (next names), speech is His second bounty: riches for hands, rhetoric for hearts. The ungraspable (previous name) consents to be heard, if not held. Sculpt one sentence well today: a true thing, beautifully said. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-268", title: "Mahendraḥ", category: "Wheel", summary: "Great Indra, lord of lords. Mahendra crowns kingship: sovereignty's summit, command's climax, the gods' king outranked by the King of kings. Indra's thunder, rain, and battle-glory are deputized splendours — lightning on loan. The verse stations cosmic kingship between eloquence and wealth: command that speaks well and gives richly. Crown one command kindly today: let an instruction carry both clarity and generosity. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-269", title: "Vasudaḥ", category: "Wheel", summary: "Giver of wealth and pleasures. Vasuda releases riches: prosperity poured, enjoyment endowed, the treasure (nidhi, name 30) disbursing through history. Giving follows kingship (previous name) as policy follows throne — sovereignty expresses as liberality. Wealth here is guiltless: enjoyment endowed by the Lord is enjoyment sanctified. Endow one enjoyment today: fund someone's gladness without ledger. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-270", title: "Vasuḥ", category: "Wheel", summary: "Wealth itself (named again). Riches essential, not merely dispensed: prosperity as being, abundance as nature — the Giver (previous name) turning out to be the gift, donor and donation one substance. Indwelling enrichment: His presence is the riches of the poorest heart, no interior bankrupt where He tenants. Be abundant once today: carry plenty inside regardless of outside. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-271", title: "Naikarūpaḥ", category: "Wheel", summary: "Of infinite forms. Naikarūpa multiplies shapes past count: faces unending, variety as verity, the One fluent in every figure. After wealth-names, multiplicity reads as generosity of self — He spends forms the way He spends riches, freely. No single icon exhausts; each is a true face, none the whole face. Vary once today variously: meet the many-formed in an unexpected form. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-272", title: "Bṛhadrūpaḥ", category: "Wheel", summary: "Vast, infinite in dimension. Bṛhadrūpa magnifies past conceiving: size surpassing sight, extent exceeding estimate — the many forms (previous name) gathered into one vastness that contains them. Vastness here is shelter, not threat: magnitude that accommodates rather than crushes. Extend once today extensively: widen a mercy beyond its usual borders. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-273", title: "Śipiviṣṭaḥ", category: "Wheel", summary: "Pervader of rays, the Yajurvedic epithet of Viṣṇu. Śipiviṣṭa is light entering all: rays penetrating, life sustained in all, the Sun's filaments as His fingers. The old commentators dispute the syllables — bald, dwarf-guised, ray-clad — and the dispute itself teaches: the name is deliberately dense, a knot only devotion unties. Penetrate once today luminously: let one attention-ray enter a dark place kindly. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-274", title: "Prakāśanaḥ", category: "Wheel", summary: "The revealer, illuminator-consciousness. Prakāśana manifests mercy as light: hidden made plain, dark made day, the ray-pervader (previous name) turning revealer — penetration ripening into disclosure. Revelation is rescue by illumination: He saves by showing. The verse closes on disclosure after mystery (durdhara): the hard-to-hold consents to be beheld. Reveal one hidden good today: bring a concealed kindness into light. (Stotra verse 29.)", relatedVerseIds: ["vs-029"] },
  { id: "vs-nama-275", title: "Ojastejodyutidharaḥ", category: "Fire-Sun", summary: "Bearer of vigour, brilliance and splendour together — one name, ojas-tejas-dyuti united. Lustre triple: vitality's pressure, radiance's clarity, beauty's charm borne as one burden lightly. The fire-sun arc opens with graduated light, each grade refining the last — force ripening into glow, glow into loveliness. Bear one lustre lightly today: strength without heaviness. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-276", title: "Prakāśātmā", category: "Fire-Sun", summary: "The effulgent Self. Prakāśātman is being as brightness: existence as illumination, the Self self-lit needing no lamp. After triple lustre (previous name) comes lustre's owner — radiance traced to its resident. To know Him is to be lit from inside rather than informed from outside. Shine selfly once today: one act from inward light rather than outward approval. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-277", title: "Pratāpanaḥ", category: "Fire-Sun", summary: "Who emits ripening heat. Pratāpana warms purposefully: scorching that matures, burning that blesses — the Sun that ripens grain, the discipline that ripens souls. Heat here is horticulture, not punishment; intensity in service of sweetness. The effulgent Self (previous name) turns agriculturist. Mature one heat kindly today: let an intensity ripen something rather than scorch someone. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-278", title: "Ṛddhaḥ", category: "Fire-Sun", summary: "Ever full of prosperity. Ṛddha is plenty as state rather than stroke: fullness permanent, fortune as climate, abundance that neither arrives nor departs but abides. After heat that ripens comes harvest that remains — ripening's reward stabilized. Scarcity is the devotee's illusion; fullness the fact. Abide once today plentifully: act from enough rather than from lack. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-279", title: "Spaṣṭākṣaraḥ", category: "Fire-Sun", summary: "Clearly indicated by Om's syllables. Spaṣṭākṣara spells mystery plainly: the Imperishable lettered, the ineffable alphabetized — a-pronounceable radiance condensing into pronounceable a-u-m. Light graduates into language here: vigour, brilliance, splendour, self, heat, fullness — then syllables. The infinite consents to spelling. Spell one mystery plainly today: say a deep thing in clear words. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-280", title: "Mantraḥ", category: "Fire-Sun", summary: "The sacred formula itself. Mantra is sound salvific: syllables that save, utterance that liberates — the spelled mystery (previous name) empowered to rescue its speaker. He is not merely indicated by mantra but is mantra: to utter rightly is to touch. The verse's arc from light to syllables docks here — radiance you can pronounce, now pronounced. Utter one saving sound today slowly, tasting each syllable. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-281", title: "Candrāṃśuḥ", category: "Fire-Sun", summary: "Pleasant as moon-rays. Candrāṃśu cools what sun-splendour kindles: gentleness beamed, soothing shone, the scorching Lord (pratāpana) wearing moonlight as counter-robe. Fierceness and gentleness are one Lord's two chemistries — heat to ripen, coolness to comfort. After mantra's fire comes moonlight's balm: utterance that soothes. Soothe once today moonlike: cool one fevered heart, beginning with your own. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-282", title: "Bhāskaradyutiḥ", category: "Fire-Sun", summary: "Effulgence of the sun. Bhāskaradyuti launches morning: daybreak divine, light issued daily, the world re-illumined like a manuscript brought to window. Moon-rays (previous name) yield to sun-splendour — gentleness and majesty alternating as the verse breathes out and in. Both are His: cooling and kindling, comfort and command. Launch one morning brightly today: begin something in full light. (Stotra verse 30.)", relatedVerseIds: ["vs-030"] },
  { id: "vs-nama-283", title: "Amṛtāṃśūdbhavaḥ", category: "Fire-Sun", summary: "Born of the nectar-rayed moon from the milk-ocean. Amṛtāṃśūdbhava rises ambrosially: churned forth sweet from the cosmic churning, delivered delightful — the moon, and with it soma and healing, emerging fromwhite surf. Origin as emergence-from-sweetness teaches that auspicious things surface from stirred depths. The new verse opens on nectar-birth before sun-glory: coolness gestating heat. Emerge once today sweetly: surface from a churning with something healing. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-284", title: "Bhānuḥ", category: "Fire-Sun", summary: "Self-shining Lord, the sun. Bhānu is luminosity original: light unborrowed, shining self-sourced, day's king needing no coronation. After nectar-birth (previous name) comes self-shining — the derived moon yielding to the underived Sun, sweetness to sovereignty. All borrowed lights — intellect, fame, pleasure — borrow from this unborrowed one. Shine once today self-sourced: one gladness owing nothing to circumstance. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-285", title: "Śaśabinduḥ", category: "Fire-Sun", summary: "Moon marked like a hare's spot. Śaśabindu wears blemish beauteously: the hare-mark adorning perfection, spot enhancing rather than marring — imperfection taken into beauty's service. After self-shining sun comes spotted moon: majesty consenting to marks, glory carrying a gentle flaw so devotees need not fear their own. Adorn one spot gracefully today: let a small imperfection serve love. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-286", title: "Sureśvaraḥ", category: "Fire-Sun", summary: "God of gods. Sureśvara is worship's object worshipped by worship's objects: the gods themselves — Indra, Agni, all bright ones — bowing toward the Brightness they borrow. Divinity has a deity; heaven has a heaven. The verse stations this supremacy between moon-marks and medicine: supremacy that spots itself with gentleness and spends itself in healing. Worship once today upwardly: honour what your honours honour. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-287", title: "Auṣadham", category: "Fire-Sun", summary: "Divine medicine of the world. Auṣadha medicates existence: being healed, the cosmos nursed, suffering treated at its root rather than merely comforted at its surface. Supremacy (previous name) expresses as pharmacy — the highest stooping to dosage, the God of gods compounding remedies. Healing is sovereignty in work-clothes. Heal one world-pain today: a small, concrete dose of relief. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-288", title: "Jagataḥ setuḥ", category: "Fire-Sun", summary: "Bridge across becoming's waters. Jagataḥ setu spans samsāra: floods foot-pathed, gulfs crossed, the sundered joined — sandhātā (name 201) now engineered as crossing. Medicine (previous name) heals; bridge conveys: two salvations, one treating sickness, one spanning separation. Every crossing — apology, forgiveness, return — walks this bridge. Cross one flood today bridged: use His span instead of swimming. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-289", title: "Satyadharmaparākramaḥ", category: "Fire-Sun", summary: "Heroic champion of truth and dharma — one name, satya-dharma-parākrama combined. Valour vindicating: right defended mightily, truth fought for, the lion's temper (verse 22) now enlisted as dharma's guard. The verse seals medicine and bridge with championship: healing and spanning protected by strength. Might serves right; force has a brief — truth-and-dharma. Fight one right mightily today, under that brief. (Stotra verse 31.)", relatedVerseIds: ["vs-031"] },
  { id: "vs-nama-290", title: "Bhūtabhavyabhavannāthaḥ", category: "Fire-Sun", summary: "Lord of beings past, future and becoming (named again). Time lorded thrice over: tenses all tenanted by Him, memory, foresight and attention three courts of one King. The early bhūtabhavyabhavatprabhu (name 4) returns after fire, sun, medicine and bridge — temporality re-claimed at higher altitude. Nothing when-ed escapes His whence. Tenant one tense trustingly today: lodge a regret, a dread, or this moment with its Lord. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-291", title: "Pavanaḥ", category: "Fire-Sun", summary: "Wind filling the universe. Pavana airs existence: breath boundless, breeze as His gesture, the three-times Lord (previous name) ventilating time itself. Wind here is motion sanctified — circulation against stagnation, freshness against staleness. What moves does not rot; what breathes does not stagnate. Gesture once today breezily: stir one stagnant corner with fresh air. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-292", title: "Pāvanaḥ", category: "Fire-Sun", summary: "The purifier, power within the wind. Pāvana cleanses by current: air washing worlds, breath bathing beings — motion (previous name) ripening into ablution. Wind carries; purifier clarifies: the same element, deepened from movement to medicine. Every breath exhales staleness when offered. Bathe once today breathfully: a slow exhalation as cleansing. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-293", title: "Analaḥ", category: "Fire-Sun", summary: "Fire. Anala is flame's godhead: burning bright, hunger holy, light liberated from fuel — the wheel's first lever (vahni, name 233) returning at higher heat. Wind and purifier (previous names) yield to flame: motion and washing crowned by transformation. Fire does what wind and water cannot — unmake and remake. Burn once today brightly: feed one impurity to transformation. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-294", title: "Kāmahā", category: "Fire-Sun", summary: "Destroyer of base desires. Kāmahan weeds wanting: cravings cleared, lusts lifted — desire's field cleared for noble sowing. The kāma-cluster opens with destruction so that fulfilment (next names) never reads as indulgence: cleared ground precedes sowing. Renunciation here is gardening, not arson. Weed one wanting today: name a base craving and lift it out by the roots. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-295", title: "Kāmakṛt", category: "Fire-Sun", summary: "Fulfiller of noble desires. Kāmakṛt warrants wanting: right wishes realized, prayers performed — the cleared field (previous name) sown and watered. Destruction and making are one Lord's two hands on desire: weeding and sowing, no to rot, yes to fruit. Desire itself is not the enemy; misdirection is. Wish once today rightly: a noble desire, plainly asked. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-296", title: "Kāntaḥ", category: "Fire-Sun", summary: "Enchanting in form, the beloved. Kānta is beauty beloved: loveliness loved, charm cherished — desire's object wearing a face. After destroying and making desires comes the Beloved who draws them: fulfilment has features, longing has an address. The Absolute is lovely — doctrine as romance. Cherish one charm today: behold a beauty as His feature. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-297", title: "Kāmaḥ", category: "Fire-Sun", summary: "Desired by seekers — love itself. Kāma completes the cluster's inward turn: longing's object becoming longing's substance, yearning's target revealed as yearning's own heart. He is not only beloved (previous name) but love — the devotee's affection discovered to be His presence wearing the devotee's shape. Long once today longingly: let the yearning itself be worship. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-298", title: "Kāmapradaḥ", category: "Fire-Sun", summary: "Supplier of desired objects. Kāmaprada provisions prayers: wants warranted with goods, needs supplied — the love-cluster's practical seal. Destroying, making, enchanting, embodying desire all terminate in supplying: the psychology completes in providence. Renunciation and fulfilment held by one Lord (verse theme). Supply one need today: answer someone's right wanting as His cashier. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-299", title: "Prabhuḥ", category: "Fire-Sun", summary: "The great Lord (named again). Lordship restated after love's grammar: desire's whole cycle — destroyed, made, beloved, embodied, granted — owned by its Master, lest devotion mistake tenderness for softness. Might that needs no display returns exactly where sweetness peaked. The Master of love is still Master. Own one desire masterfully today: hold it, examine it, direct it — as owner, not owned. (Stotra verse 32.)", relatedVerseIds: ["vs-032"] },
  { id: "vs-nama-300", title: "Yugādikṛt", category: "Fire-Sun", summary: "Maker of the yugas' dawns. Yugādikṛt inaugurates ages: time's chapters headed, epochs opened — the three-times Lord (name 290) now authoring time's paragraphs. Every dawn (daily) and every yuga-dawn (cosmic) is His opening sentence. Beginnings have an Author; history has an Editor. Open one epoch hopefully today: begin something as though ages turn on small dawns — they do. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
];